from funcy import memoize, cache, reraise
from funcy.calc import SkipMemoization

for decorate in (memoize, memoize(), memoize(key_func=lambda x, **kw: x), cache(60)):
    calls = []
    @decorate
    def f(x, **kw):
        calls.append(x)
        return len(calls)
    memory = f.memory
    assert f(1, a=2, b=3) == f(1, b=3, a=2) == 1
    assert f(2) == 2
    f.invalidate(1, b=3, a=2)
    f.invalidate(1, a=2, b=3)
    assert f(1, a=2, b=3) == 3
    assert f(2) == 2
    f.invalidate_all()
    assert f.memory is memory and not memory
    assert f(2) == 4
    assert f.skip is SkipMemoization

@memoize(key_func=lambda values, **kw: len(values))
def f(values, **kw):
    return object()
a = f([1])
f.invalidate([2])
assert f([1]) is not a

for value in (None, 0, 'fallback'):
    @cache(60)
    def f():
        raise f.skip(value)
    assert f() == value and not f.memory
assert cache.skip is memoize.skip is SkipMemoization

original = ValueError('original')
seen = []
def transform(error):
    seen.append(error)
    return RuntimeError('transformed: ' + str(error))
@reraise(ValueError, transform)
def fail():
    raise original
for operation in (fail, fail):
    try:
        operation()
    except RuntimeError as error:
        assert str(error) == 'transformed: original'
        assert error.__cause__ is original
    else:
        raise AssertionError('did not transform')
assert seen == [original, original]
for into in (RuntimeError, RuntimeError('fixed')):
    try:
        with reraise(ValueError, into):
            raise original
    except RuntimeError as error:
        assert error.__cause__ is original
        assert error.args == (() if into is RuntimeError else ('fixed',))
    else:
        raise AssertionError('did not reraise')
with reraise(ValueError, lambda error: 1 / 0):
    pass
print('Focused API and exception transformation checks passed')
